const MENUS=[['dashboard','Dashboard',LayoutDashboard],['billing','New Bill',CirclePlus],['orders','Orders',ReceiptText],['menu','Items',HandHeart],['customers','Customers',Users],['reports','Reports',ChartNoAxesCombined],['settings','Settings',Settings]];
const money=n=>'₹'+Number(n||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
const can=(user,key)=>!!(user?.is_admin||user?.permissions.includes(key));
const allowed=(user,key)=>key==='reports'?can(user,'reports')||can(user,'report_pos')||can(user,'report_services')||can(user,'report_gst'):key==='reports_pos'?can(user,'reports')||can(user,'report_pos'):key==='reports_services'?can(user,'reports')||can(user,'report_services'):key==='reports_gst'?can(user,'reports')||can(user,'report_gst'):key==='categories'?can(user,'menu'):key==='users'||key==='audit'?!!user?.is_admin:can(user,key);
const staffPermissions=p=>[...new Set(p.filter(k=>k!=='closing').flatMap(k=>k==='reports'?['report_pos','report_services','report_gst']:[k]))];
const ACCESS_MENUS=MENUS.filter(([key])=>key!=='reports').concat([['report_pos','Reports → POS Reports'],['report_services','Reports → Item Sale Report'],['report_gst','Reports → GST Reports'],['cancel_bills','Cancel bills (use with Orders access)']]);

function useData(path){const [data,setData]=useState(null),[error,setError]=useState(''),[loading,setLoading]=useState(true),[version,setVersion]=useState(0);useEffect(()=>{let alive=true;if(!path){setData([]);setLoading(false);return}setLoading(true);setError('');api(path).then(d=>{if(alive)setData(d)}).catch(e=>{if(alive)setError(e.message)}).finally(()=>{if(alive)setLoading(false)});return()=>{alive=false}},[path,version]);return {data,error,loading,reload:()=>setVersion(v=>v+1)}}
function ErrorBox({error}){return error?<div className="error" role="alert">{error}</div>:null}
function Loading(){return <div className="loading">Loading workspace…</div>}
function PageHead({title,subtitle,children}){return <div className="pagehead"><div><h1>{title}</h1><p className="muted">{subtitle}</p></div>{children}</div>}
function Modal({title,onClose,children}){const titleId=useId();const ref=useRef(),closeRef=useRef(onClose);closeRef.current=onClose;useEffect(()=>{const old=document.activeElement;ref.current?.querySelector('input,button,select,textarea')?.focus();function key(e){if(e.key==='Escape')closeRef.current();if(e.key==='Tab'){const nodes=[...ref.current.querySelectorAll('button,input,select,textarea')].filter(n=>!n.disabled);if(!nodes.length)return;if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0].focus()}}}document.addEventListener('keydown',key);return()=>{document.removeEventListener('keydown',key);old?.focus()}},[]);return <div className="modalwrap" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal" role="dialog" aria-modal="true" aria-labelledby={titleId} ref={ref}><div className="cardhead"><h2 id={titleId}>{title}</h2><button className="iconbutton" onClick={onClose} aria-label="Close"><X size={16}/></button></div>{children}</div></div>}
function Field({label,children}){return <label className="field">{label}{children}</label>}
function Login({onLogin}){const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[show,setShow]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState('');async function submit(e){e.preventDefault();setBusy(true);setError('');try{onLogin(await post('/auth/login',{username:email,passcode:password}));setPassword('')}catch(e){setError(e.message)}finally{setBusy(false)}}return <section className="login"><div className="loginbox"><div className="brandpanel"><div className="brandmark"><div className="symbol"><img src="/agraharam-brand.png" alt="Agraharam Special"/></div><div className="brandname">AGRAHARAM<span>ITEM POS</span></div></div><h2>Item POS</h2><p>Simple item billing, customer records and sales reporting.</p></div><form className="signin" onSubmit={submit}><h1>Welcome Back</h1><p className="muted">Sign in to Agraharam Item POS</p><Field label="Username"><input type="text" autoComplete="username" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="Your username"/></Field><Field label="Passcode"><div className="passwordbox"><input type={show?'text':'password'} autoComplete="current-password" required value={password} onChange={e=>setPassword(e.target.value)} maxLength={128}/><button type="button" onClick={()=>setShow(!show)} aria-label={show?'Hide password':'Show password'}>{show?<EyeOff size={19}/>:<Eye size={19}/>}</button></div></Field><ErrorBox error={error}/><button className="primary" disabled={busy}>{busy?'Signing in…':'Sign in'}</button><div className="foot">Agraharam POS · Secure Staff Access</div></form></div></section>}
function StatCards({data}){return <div className="stats">{[['Total sales',money(data.total_sales),'Completed bills only'],['Bills',data.bill_count,'Completed bills'],['Cancelled',money(data.cancelled_amount||0),(data.cancelled_count||0)+' cancelled bills'],['Cash',money(data.payments.Cash),'Cash collections'],['UPI',money(data.payments.UPI),'UPI collections'],['Card',money(data.payments.Card),'Card collections']].map(([label,value,sub])=><div className="stat" key={label}><span>{label}</span><strong>{value}</strong><span>{sub}</span></div>)}</div>}
function Summary({data}){return <><StatCards data={data}/><div className="twocol"><div className="card"><h2>Popular items</h2>{data.popular.length?<div className="tablewrap"><table><thead><tr><th>Item</th><th>Quantity</th><th>Sales</th></tr></thead><tbody>{data.popular.map(p=><tr key={p.name}><td>{p.name}</td><td>{p.qty}</td><td>{money(p.sales)}</td></tr>)}</tbody></table></div>:<div className="empty">Completed bills will appear here.</div>}</div><div className="card"><h2>Payment breakdown</h2>{Object.entries(data.payments).map(([p,n])=><div className="chartrow" key={p}><span>{p}</span><div className="bar"><div style={{width:(data.total_sales?n/data.total_sales*100:0)+'%'}}/></div><strong className="small">{money(n)}</strong></div>)}<div className="totalrow"><span>Included GST</span><strong>{money(data.tax)}</strong></div></div></div></>}
function Dashboard({onNavigate,user}){const r=useData('/dashboard');return <><PageHead title="Today at a glance" subtitle="Item collections for today, in India time.">{allowed(user,'billing')&&<button className="primary" onClick={()=>onNavigate('billing')}>+ Create bill</button>}</PageHead><ErrorBox error={r.error}/>{r.loading?<Loading/>:r.data&&<Summary data={r.data}/>}</>}
function BillReceipt({order,onClose}){return <Modal title="Bill receipt" onClose={onClose}><div className="receipt"><h2>{order.receipt_details?.business_name||"AGRAHARAM"}</h2><p className="receipt-caption">{order.receipt_details?.branch_name}</p><p className="small">{order.receipt_details?.legal_name}</p><p className="small">GSTIN: {order.receipt_details?.gstin||order.gst_details?.seller_gstin||"Not configured"}</p><p className="small">FSSAI: {order.receipt_details?.fssai_number||"Not configured"}</p>{order.address&&<p className="small">{order.address}</p>}{order.phone&&<p className="small">{order.phone}</p>}{order.offline&&<div className="banner">OFFLINE RECEIPT · PENDING SYNC<br/>Keep this local reference until the final bill number is assigned.</div>}{order.status==='Cancelled'&&<div className="cancelled-banner">CANCELLED BILL<br/><span>{order.cancellation?.reason}</span></div>}<p className="small">{order.bill_number}<br/>{new Date(order.created_at).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})}<br/>{order.order_type} · {order.customer_name||'Walk-in'}</p><div className="lines">{order.items.map(i=><div className="receipt-item" key={i.item_id}><span>{i.name} × {i.qty}</span><span>{money(i.line_total)}</span></div>)}<div className="totalrow" style={{marginTop:18}}><span>Subtotal</span><span>{money(order.subtotal)}</span></div><div className="totalrow"><span>CGST</span><span>{order.gst_details?.cgst!=null?money(order.gst_details.cgst):"Pending"}</span></div><div className="totalrow"><span>SGST</span><span>{order.gst_details?.sgst!=null?money(order.gst_details.sgst):"Pending"}</span></div><div className="totalrow"><span>IGST</span><span>{order.gst_details?.igst!=null?money(order.gst_details.igst):"Pending"}</span></div><div className="small"><strong>HSN/SAC summary</strong>{Object.entries(order.items.reduce((a,i)=>{const k=(i.hsn_code||i.sac_code||"Missing code")+" / "+(i.gst_rate??order.tax_rate)+"%";a[k]=(a[k]||0)+Number(i.taxable_value||0);return a},{})).map(([k,v])=><div className="totalrow" key={k}><span>{k}</span><span>{money(v)}</span></div>)}</div><div className="totalrow grand"><span>Total</span><span>{money(order.total)}</span></div><div className="receipt-payments"><strong>Payment received</strong>{(order.payments||[{method:order.payment,amount:order.total}]).map(p=><div className="totalrow" key={p.method}><span>{p.method}</span><span>{money(p.amount)}</span></div>)}</div></div><p className="small muted">Billed by <strong>{order.staff_name}</strong>{order.staff_username&&<> ({order.staff_username})</>}<br/>Thank you for visiting Agraharam!</p></div><div className="receipt-actions"><button onClick={onClose}>Close</button><button className="primary" onClick={()=>printThermal(order,order.status==='Cancelled'?'bill':'combined')}>{order.status==='Cancelled'?'Print cancelled bill':'Print bill + KOT'}</button></div></Modal>}
function Billing({branchId}){const catalog=useData('/menu'),customers=useData('/customers'),settings=useData('/settings');const [cart,setCart]=useState([]),[category,setCategory]=useState('All'),[search,setSearch]=useState(''),[payment,setPayment]=useState('Cash'),[split,setSplit]=useState({Cash:'',UPI:'',Card:''}),[customerId,setCustomerId]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false),[receipt,setReceipt]=useState(null);const requestId=useRef(crypto.randomUUID());const total=cart.reduce((n,i)=>n+i.price*i.qty,0),rate=settings.data?.tax_rate||0,subtotal=total/(1+rate/100);const splitInvalid=Object.values(split).some(v=>v!==''&&!/^\d+(\.\d{1,2})?$/.test(v));const paidCents=Object.values(split).reduce((n,v)=>n+Math.round(Number(v||0)*100),0);const billCents=Math.round(total*100);const splitEntries=Object.entries(split).filter(([,v])=>Number(v)>0).map(([method,v])=>({method,amount:Number(v)}));const splitReady=!splitInvalid&&paidCents===billCents&&splitEntries.length>=2;function add(i){requestId.current=crypto.randomUUID();setCart(c=>c.some(x=>x.id===i.id)?c.map(x=>x.id===i.id?{...x,qty:x.qty+1}:x):[...c,{...i,qty:1}])}function qty(id,d){requestId.current=crypto.randomUUID();setCart(c=>c.map(i=>i.id===id?{...i,qty:Math.min(1000,i.qty+d)}:i).filter(i=>i.qty>0))}async function checkout(){if(busy||!cart.length)return;if(!branchId){setError('Select a branch before billing');return;}setBusy(true);setError('');try{const o=await post('/orders',{branch_id:branchId,request_id:requestId.current,items:cart.map(i=>({item_id:i.id,qty:i.qty})),customer_id:customerId||null,buyer_gstin:customers.data?.find(c=>c.id===customerId)?.gstin||'',place_of_supply:settings.data?.state_code||settings.data?.gstin?.slice(0,2)||'',order_type:'Item',payment,...payment==='Split'&&{payments:splitEntries},expected_total:Number(total.toFixed(2))});printThermal(o,'combined');setCart([]);setSplit({Cash:'',UPI:'',Card:''});setPayment('Cash');requestId.current=crypto.randomUUID()}catch(e){setError(e.message)}finally{setBusy(false)}}const items=(catalog.data||[]).filter(i=>i.active);return <><PageHead title="New bill" subtitle="Select items and confirm payment."/><ErrorBox error={catalog.error||customers.error||settings.error}/>{catalog.loading||settings.loading?<Loading/>:<div className="poslayout"><section><input aria-label="Search items" placeholder="Search items…" value={search} onChange={e=>setSearch(e.target.value)}/><div className="categories">{['All',...new Set(items.map(i=>i.category))].map(c=><button key={c} className={'category '+(category===c?'active':'')} onClick={()=>setCategory(c)}>{c}</button>)}</div><div className="menu-grid">{items.filter(i=>(category==='All'||i.category===category)&&[i.name,i.code,i.sac_code].join(' ').toLowerCase().includes(search.toLowerCase())).map(i=><button className="foodcard" key={i.id} onClick={()=>add(i)} disabled={busy}><div className="item-photo">{i.image?<img src={i.image} alt="" loading="lazy"/>:<span>{i.name.slice(0,1)}</span>}</div><div className="fooddetail"><strong>{i.name}</strong><div className="price"><span>MRP {money(i.price)}</span><span className="plus">+</span></div></div></button>)}</div>{!items.length&&<div className="card empty">No items yet. Add your items and GST-inclusive prices.</div>}</section><aside className="card bill"><div className="cardhead"><div><h2>Current bill</h2><span className="small muted">{cart.reduce((n,i)=>n+i.qty,0)} items</span></div><button className="small" disabled={busy} onClick={()=>{setCart([]);setSplit({Cash:'',UPI:'',Card:''});setPayment('Cash');setCustomerId('');setError('');requestId.current=crypto.randomUUID()}}>Clear</button></div><Field label="Customer (optional)"><select disabled={busy} value={customerId} onChange={e=>{requestId.current=crypto.randomUUID();setCustomerId(e.target.value)}}><option value="">Walk-in customer</option>{customers.data?.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><div className="billitems">{cart.length?cart.map(i=><div className="billitem" key={i.id}><div className="row"><strong>{i.name}</strong><span>{money(i.price*i.qty)}</span></div><div className="row" style={{marginTop:10}}><span className="small muted">{money(i.price)} each</span><div className="qty"><button disabled={busy} onClick={()=>qty(i.id,-1)} aria-label={'Decrease '+i.name}>−</button><span>{i.qty}</span><button disabled={busy||i.qty>=1000} onClick={()=>qty(i.id,1)} aria-label={'Increase '+i.name}>+</button></div></div></div>):<div className="empty">Add items to start a bill.</div>}</div><div className="totals"><div className="totalrow grand"><span>Total</span><span>{money(total)}</span></div></div><label>Payment method</label><div className="payments">{['Cash','UPI','Card','Split'].map(p=><button key={p} disabled={busy} className={p===payment?'active':''} onClick={()=>{requestId.current=crypto.randomUUID();setPayment(p)}}>{p}</button>)}</div>{payment==='Split'&&<div className="split-panel"><p className="small">Enter amounts for two or three methods.</p>{['Cash','UPI','Card'].map(method=><label className="split-input" key={method}><span>{method}</span><input aria-label={method+' payment amount'} disabled={busy} type="number" min="0" max={total.toFixed(2)} step="0.01" placeholder="0.00" value={split[method]} onChange={e=>{requestId.current=crypto.randomUUID();setSplit(s=>({...s,[method]:e.target.value}))}}/><button type="button" className="smallbtn" disabled={busy} onClick={()=>{requestId.current=crypto.randomUUID();const others=Object.entries(split).filter(([k])=>k!==method).reduce((n,[,v])=>n+Math.round(Number(v||0)*100),0);setSplit(s=>({...s,[method]:(Math.max(0,billCents-others)/100).toFixed(2)}))}}>Balance</button></label>)}<div className={'split-balance '+(splitReady?'balanced':'')}><span>{paidCents>billCents?'Over allocated':'Remaining'}</span><strong>{money(Math.abs(billCents-paidCents)/100)}</strong></div>{splitInvalid&&<p className="error">Use positive amounts with up to two decimal places.</p>}{!splitInvalid&&paidCents===billCents&&splitEntries.length<2&&<p className="helptext">Use a single payment button when only one method is used.</p>}</div>}<p className="helptext">Verify that payment has been received before completing the bill.</p><ErrorBox error={error}/><button className="primary" disabled={busy||!cart.length||!!settings.error||customers.loading||(payment==='Split'&&!splitReady)} onClick={checkout}>{busy?'Saving bill…':'Complete bill · '+money(total)}</button></aside></div>}{receipt&&<BillReceipt order={receipt} onClose={()=>setReceipt(null)}/>}</>}
function CancelBill({order,onClose,onSaved}){const [reason,setReason]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');async function submit(e){e.preventDefault();setBusy(true);try{const cancelled=await post('/orders/'+order.id+'/cancel',{reason});onSaved();onClose();printThermal(cancelled,'bill')}catch(e){setError(e.message)}finally{setBusy(false)}}return <Modal title={'Cancel '+order.bill_number} onClose={()=>{if(!busy)onClose()}}><form onSubmit={submit}><p>Cancel this bill for {money(order.total)}? It will remain in Orders and be excluded from sales totals.</p><Field label="Cancellation reason"><textarea required minLength={3} maxLength={300} value={reason} onChange={e=>setReason(e.target.value)}/></Field><p className="helptext">Cancellation records the change. Arrange any customer refund separately.</p><ErrorBox error={error}/><div className="actions"><button type="button" disabled={busy} onClick={onClose}>Keep bill</button><button className="primary" disabled={busy}>{busy?'Cancelling…':'Confirm cancellation'}</button></div></form></Modal>}
